// 该码点字库是否有字形
inline bool fontHasChar(unsigned int cp) {
    if (cp < 0x20 || cp > 0xFFFF) return false;
    return (kFontBits[cp >> 3] >> (cp & 7)) & 1;
}

// 读一个 UTF-8 字符，返回码点；*len 收到该字符的字节数（非法序列按 1 字节、码点 0）
inline unsigned int fontNextChar(const char* s, int* len) {
    const unsigned char* p = (const unsigned char*)s;
    if (p[0] < 0x80) { *len = 1; return p[0]; }
    if ((p[0] & 0xE0) == 0xC0 && (p[1] & 0xC0) == 0x80) {
        *len = 2; return (unsigned int)(((p[0] & 0x1F) << 6) | (p[1] & 0x3F));
    }
    if ((p[0] & 0xF0) == 0xE0 && (p[1] & 0xC0) == 0x80 && (p[2] & 0xC0) == 0x80) {
        *len = 3; return (unsigned int)(((p[0] & 0x0F) << 12) | ((p[1] & 0x3F) << 6) | (p[2] & 0x3F));
    }
    if ((p[0] & 0xF8) == 0xF0 && (p[1] & 0xC0) == 0x80 && (p[2] & 0xC0) == 0x80 && (p[3] & 0xC0) == 0x80) {
        *len = 4;
        return (unsigned int)(((p[0] & 0x07) << 18) | ((p[1] & 0x3F) << 12) | ((p[2] & 0x3F) << 6) | (p[3] & 0x3F));
    }
    *len = 1; return 0;
}

// 整串是否都有字形（空格/换行跳过不判）
inline bool fontHasUtf8(const char* s) {
    if (s == 0) return false;
    for (const char* p = s; *p != 0;) {
        int n = 1;
        const unsigned int cp = fontNextChar(p, &n);
        if (cp != 0 && cp != 0x20 && cp != 0x09 && cp != 0x0A && !fontHasChar(cp)) return false;
        p += n;
    }
    return true;
}

// 过滤：只保留字库有字形的字符（外部文案喂给控件之前的兜底）
inline std::string fontFilterUtf8(const std::string& in) {
    std::string out;
    for (size_t i = 0; i < in.size();) {
        int n = 1;
        const unsigned int cp = fontNextChar(in.c_str() + i, &n);
        if (cp == 0 || cp == 0x20 || fontHasChar(cp)) out.append(in, i, (size_t)n);
        i += (size_t)n;
    }
    return out;
}

